SET search_path TO axsuck, public;

-- Swiss-system tournaments: the number of rounds is chosen by the admin when
-- the tournament is created.
ALTER TABLE tournaments
  ADD COLUMN IF NOT EXISTS swiss_rounds SMALLINT
    CHECK (swiss_rounds IS NULL OR swiss_rounds BETWEEN 1 AND 15);

-- Swiss matches use bracket = 'sw' with round = the Swiss round number.
-- Migration 010 added the bracket CHECK inline, so its name is generated by
-- Postgres; drop whichever check constraint covers the bracket column.
DO $$
DECLARE c record;
BEGIN
  FOR c IN
    SELECT conname
    FROM pg_constraint
    WHERE conrelid = 'axsuck.matches'::regclass
      AND contype = 'c'
      AND pg_get_constraintdef(oid) LIKE '%bracket%'
  LOOP
    EXECUTE format('ALTER TABLE axsuck.matches DROP CONSTRAINT %I', c.conname);
  END LOOP;
END $$;

ALTER TABLE axsuck.matches
  ADD CONSTRAINT matches_bracket_check
  CHECK (bracket IN ('main', 'wb', 'lb', 'gf', 'sw'));
